// scripts/prepare-data.py from the custodians' repository) — nothing is typed by hand.
import raw from './data/taxonomy.json'

export type Rel = { t: string; to: string }
export type InRel = { t: string; from: string }
export interface Concept {
  id: string
  label: string
  syn: string[]
  facet: string
  level: number
  parent: string | null
  children: string[]
  path: string[]
  root: string
  rootFacet: string
  def: string
  defSrc: string
  srcFamily: string
  srcSub: string
  stage: string
  scope: string
  domain: string
  impact: string
  aTag: string
  aCond: string
  mTag: string
  mCond: string
  rels: Rel[]
  inRels: InRel[]
  prov: string[]
  example: string
  refs: string[]
  group: string
  anchorA: boolean
  hazard: boolean
  anchorM: boolean
}
export interface Named { name: string; def: string }
export interface Change { type: string; id: string; label: string; facet: string; level: string; parent: string; field: string; v4: string; v5: string; why: string }
export interface SynChange { type: string; syn: string; fromId: string; fromLabel: string; toId: string; toLabel: string; why: string }
export interface Retired { id: string; label: string; facet: string; successor: string; successorIds: string[]; reason: string }
export interface Dna { word: string; type: string; date: string; reason: string; status: string; statusIds: string[] }
export interface Fair { principle: string; test: string; state: string; text: string }
export interface Decision { date: string; issue: string; kind: string; proposal: string; decision: string; reason: string; redirect: string; change: string; decidedByRole: string }

interface Data {
  meta: {
    title: string; version: string; versionDate: string; contentBuiltAt: string; sourceCommit: string
    sourceCommitDate: string; repo: string; site: string; preparedAt: string
    validation: { errors: number; warnings: number; info: number }
  }
  vocab: {
    facets: Named[]; levels: Named[]; pathwayStages: Named[]; scopes: Named[]; adaptationTags: Named[]
    mitigationTags: Named[]; domains: Named[]; impactAreas: Named[]; relationTypes: Named[]; provClasses: string[]
  }
  concepts: Concept[]
  changes: Change[]
  synChanges: SynChange[]
  retired: Retired[]
  dna: Dna[]
  fair: Fair[]
  decisions: Decision[]
}

export const DATA = raw as unknown as Data
export const META = DATA.meta
export const VOCAB = DATA.vocab
export const CONCEPTS = DATA.concepts
export const BY_ID: Map<string, Concept> = new Map(CONCEPTS.map((c) => [c.id, c]))
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
/** "2026-09-23" -> "23 Sep 2026" (date part only, no time-zone shift). */
export function fmtDate(iso: string) {
  const [y, m, d] = iso.slice(0, 10).split('-').map(Number)
  return `${d} ${MONTHS[m - 1]} ${y}`
}

export const officialUrl = (id: string) => `${META.site}terms/${id}.html`
export const versionLabel = `v${META.version} (${fmtDate(META.versionDate)})`

