// ---------------------------------------------------------------- relations
export const REL_DEF: Record<string, string> = Object.fromEntries(VOCAB.relationTypes.map((r) => [r.name, r.def]))
export const REL_TYPES = VOCAB.relationTypes.map((r) => r.name)
/** Visual family for edge styling (solid / dashed / dotted). Derived from the relation names. */
export function relFamily(t: string): 'chain' | 'mitigation' | 'partitive' {
  if (t === 'part-of' || t === 'composed-of') return 'partitive'
  if (t === 'emits' || t === 'sequesters' || t === 'reduces-emissions') return 'mitigation'
  return 'chain'
}
export const REL_FAMILY_LABEL = { chain: 'Results-chain relations', mitigation: 'Mitigation relations', partitive: 'Part–whole relations' }

// ---------------------------------------------------------------- helpers
export function countBy<T>(arr: T[], key: (x: T) => string | string[]): Map<string, number> {
  const m = new Map<string, number>()
  for (const x of arr) {
    const k = key(x)
    for (const kk of Array.isArray(k) ? k : [k]) m.set(kk, (m.get(kk) ?? 0) + 1)
  }
  return m
}
export const pct = (n: number, d: number, digits = 0) => (d ? ((100 * n) / d).toFixed(digits) : '0') + '%'
export const fmt = (n: number) => n.toLocaleString('en-GB')

export const tagKind = (tag: string): 'specific' | 'conditional' | 'na' =>
  tag.endsWith('-specific') ? 'specific' : tag.endsWith('-conditional') ? 'conditional' : 'na'

/** Decision rules: distinct per-facet condition sentences (excluding Intrinsic / n/a). */
export interface Rule { key: string; lens: 'adaptation' | 'mitigation'; subject: string; text: string; when: string; note: string; not: string; concepts: Concept[] }
function buildRules(lens: 'adaptation' | 'mitigation'): Rule[] {
  const m = new Map<string, Concept[]>()
  for (const c of CONCEPTS) {
    const t = lens === 'adaptation' ? c.aCond : c.mCond
    if (!t || t === 'Intrinsic' || t.startsWith('n/a')) continue
    if (!m.has(t)) m.set(t, [])
    m.get(t)!.push(c)
  }
  const rules: Rule[] = []
  for (const [text, cs] of m) {
    const subjMatch = FACET_ORDER.slice().sort((a, b) => b.length - a.length).find((f) => text.startsWith(f))
    const subject = subjMatch ?? text.split(' ')[0]
    const [whenRaw, ...notParts] = text.split(/;\s*NOT\s+/)
    const lensWord = lens
    let when = whenRaw.trim().replace(/\.$/, '')
    let note = ''
    const m = when.match(/^(.*?)(?:;\s*)?\bcounts as (?:adaptation|mitigation) when\s+(.*)$/i)
    if (m) {
      note = m[1].trim() === subject ? '' : m[1].trim()
      when = m[2]
    } else when = when.replace(new RegExp('^' + subject + '\\s+'), 'it ')
    const not = notParts.join('; ').trim().replace(/^(adaptation|mitigation)\s+when\s+/i, '').replace(/\.$/, '')
    rules.push({ key: `${lensWord}:${subject}`, lens, subject, text, when, note, not, concepts: cs })
  }
  rules.sort((a, b) => b.concepts.length - a.concepts.length)
  return rules
}
export const RULES = { adaptation: buildRules('adaptation'), mitigation: buildRules('mitigation') }

export function degree(c: Concept) {
  return c.rels.length + c.inRels.length
}

export function descendantsCount(id: string): number {
  const c = BY_ID.get(id)
  if (!c) return 0
  let n = 0
  for (const ch of c.children) n += 1 + descendantsCount(ch)
  return n
}

/** Changes per concept id (term-level + synonym-level). */
export const CHANGES_BY_ID: Map<string, typeof DATA.changes> = new Map()
for (const ch of DATA.changes) {
  if (!CHANGES_BY_ID.has(ch.id)) CHANGES_BY_ID.set(ch.id, [])
  CHANGES_BY_ID.get(ch.id)!.push(ch)
}
export const SYN_CHANGES_BY_ID: Map<string, SynChange[]> = new Map()
for (const s of DATA.synChanges) {
  for (const id of new Set([s.fromId, s.toId].filter(Boolean))) {
    if (!SYN_CHANGES_BY_ID.has(id)) SYN_CHANGES_BY_ID.set(id, [])
    SYN_CHANGES_BY_ID.get(id)!.push(s)
  }
}

export const ID_RE = /\b(?:CRK|CDI|SYS|INT|OUT|OTC|IMP|ADP|TRT|STK|CCC)_\d+\b/g
